const foxX = useSharedValue(430);
const foxY = useSharedValue(250);

const scale = useSharedValue(0.28);

const translateX = useSharedValue(160);
const translateY = useSharedValue(100);

const savedTranslateX = useSharedValue(160);
const savedTranslateY = useSharedValue(100);

const savedScale = useSharedValue(0.28);
const startTranslateX = useSharedValue(250);
const startTranslateY = useSharedValue(200);
const startScale = useSharedValue(1);

const pinchGesture = Gesture.Pinch()
  .onStart(() => {
    startScale.value = scale.value;
    startTranslateX.value = translateX.value;
    startTranslateY.value = translateY.value;
  })
  .onUpdate((event) => {
  const nextScale =
    startScale.value * event.scale;

  const limitedScale = Math.max(
    0.2,
    Math.min(nextScale, 0.8)
  );

  translateX.value =
    event.focalX -
    (event.focalX - startTranslateX.value) *
      (limitedScale / startScale.value);

  translateY.value =
    event.focalY -
    (event.focalY - startTranslateY.value) *
      (limitedScale / startScale.value);

  scale.value = limitedScale;
})
  .onEnd(() => {
    savedScale.value = scale.value;
    savedTranslateX.value = translateX.value;
    savedTranslateY.value = translateY.value;
  });



const animatedStyle =
  useAnimatedStyle(() => {
    return {
      transform: [
        { translateX: translateX.value },
        { translateY: translateY.value },
        { scale: scale.value },
      ],
    };
  });

  const foxAnimatedStyle = useAnimatedStyle(() => {
  return {
    left: foxX.value,
    top: foxY.value,
  };
});

const isFoxOutsideVillage = (x: number, y: number) => {
  const foxGrid = screenToRawGrid(x, y);

  return (
    foxGrid.col < 0 ||
    foxGrid.col > GRID_SIZE - 1 ||
    foxGrid.row < 0 ||
    foxGrid.row > GRID_SIZE - 1
  );
};

const isFoxBlockedByBuilding = (x: number, y: number) => {
  const foxGrid = screenToGrid(x, y);

  return placedBuildings.some((building) => {
    const size =
      buildingSizes[
        building.id as keyof typeof buildingSizes
      ] ?? { cols: 1, rows: 1 };

    for (let c = 0; c < size.cols; c++) {
      for (let r = 0; r < size.rows; r++) {
        if (
          building.col + c === foxGrid.col &&
          building.row + r === foxGrid.row
        ) {
          return true;
        }
      }
    }

    return false;
  });
};

useEffect(() => {
  const directions = [
    'downRight',
    'downLeft',
    'upRight',
    'upLeft',
  ] as const;

  const interval = setInterval(() => {
    const randomDirection =
      directions[Math.floor(Math.random() * directions.length)];

    setFoxDirection(randomDirection);

    let nextX = foxX.value;
    let nextY = foxY.value;

    if (randomDirection === 'downRight') {
      nextX += 40;
      nextY += 20;
    }

    if (randomDirection === 'downLeft') {
      nextX -= 40;
      nextY += 20;
    }

    if (randomDirection === 'upRight') {
      nextX += 40;
      nextY -= 20;
    }

    if (randomDirection === 'upLeft') {
      nextX -= 40;
      nextY -= 20;
    }

    const minX = 120;
const maxX = 1200;

const minY = 80;
const maxY = 900;

nextX = Math.max(minX, Math.min(nextX, maxX));
nextY = Math.max(minY, Math.min(nextY, maxY));

if (isFoxOutsideVillage(nextX, nextY)) {
  return;
}

if (isFoxBlockedByBuilding(nextX, nextY)) {
  return;
}

foxX.value = withTiming(nextX, { duration: 900 });
foxY.value = withTiming(nextY, { duration: 900 });
  }, 1300);

  return () => clearInterval(interval);
}, []);

