  const saveTimeGoalToDayRecords = async (
  title: string,
  startAt: string,
  endAt: string
) => {
  const raw = await AsyncStorage.getItem('daily_time_records_v1');
  const records = raw ? JSON.parse(raw) : {};

  const start = new Date(startAt);
  const end = new Date(endAt);

  let cursor = new Date(start);

  while (cursor < end) {
    const dateKey = formatDateKey(cursor);

    const h24 = cursor.getHours();
    const mStr = cursor.getMinutes() < 30 ? '00' : '30';

    const key = `${
      h24 < 12 ? '낮' : '저녁'
    }_${h24 % 12 === 0 ? 12 : h24 % 12}_${mStr}`;

    records[dateKey] = {
      ...(records[dateKey] ?? {}),
      [key]: title,
    };

    cursor.setMinutes(cursor.getMinutes() < 30 ? 30 : 60);
  }

  await AsyncStorage.setItem(
    'daily_time_records_v1',
    JSON.stringify(records)
  );
};

const addExerciseCaloriesToDay =
  async ({
    calories,
    minutes,
    title,
    targetDateKey,
    goalId,
    recordId,
  }: {
    calories: number;
    minutes: number;
    title: string;
    targetDateKey: string;
    goalId:
      | string
      | number;
    recordId: string;
  }) => {
    const safeCalories =
      Math.max(
        0,
        Math.round(
          Number(
            calories
          ) || 0
        )
      );

    if (
      safeCalories <= 0
    ) {
      return 0;
    }

    const [
      totalsRaw,
      logsRaw,
    ] =
      await Promise.all([
        AsyncStorage.getItem(
          'daily_exercise_calories_v1'
        ),

        AsyncStorage.getItem(
          EXERCISE_CALORIE_LOGS_KEY
        ),
      ]);

    const savedTotals:
      Record<
        string,
        number
      > =
      totalsRaw
        ? JSON.parse(
            totalsRaw
          )
        : {};

    const savedLogs:
      any[] =
      logsRaw
        ? JSON.parse(
            logsRaw
          )
        : [];

    /*
     * 같은 홈 기록이
     * 두 번 저장되는 것을
     * 방지합니다.
     */
    const existingLog =
      savedLogs.find(
        (log: any) =>
          String(
            log?.recordId ??
              ''
          ) ===
          String(
            recordId
          )
      );

    if (existingLog) {
      return (
        Number(
          existingLog.calories
        ) || 0
      );
    }

    const nextTotals = {
      ...savedTotals,

      [targetDateKey]:
        (
          savedTotals[
            targetDateKey
          ] ?? 0
        ) +
        safeCalories,
    };

    const nextLog = {
      id:
        `timer_${recordId}`,

      date:
        targetDateKey,

      title:
        title.trim() ||
        '운동',

      calories:
        safeCalories,

      source:
        'timer' as const,

      durationMinutes:
        Math.max(
          0,
          Math.round(
            minutes
          )
        ),

      goalId:
        String(
          goalId
        ),

      recordId:
        String(
          recordId
        ),
    };

    const nextLogs = [
      nextLog,
      ...savedLogs,
    ];

    /*
     * 합계와 목록을 함께
     * 로컬에 저장합니다.
     */
    await AsyncStorage.multiSet(
      [
        [
          'daily_exercise_calories_v1',
          JSON.stringify(
            nextTotals
          ),
        ],

        [
          EXERCISE_CALORIE_LOGS_KEY,
          JSON.stringify(
            nextLogs
          ),
        ],
      ]
    );

    console.log(
      'DAY EXERCISE CALORIE SAVE DONE',
      {
        date:
          targetDateKey,

        title:
          nextLog.title,

        minutes:
          nextLog.durationMinutes,

        calories:
          safeCalories,

        recordId,
      }
    );

    return safeCalories;
  };

  const getDistanceKm = (a: any, b: any) => {
  const R = 6371;
  const dLat = ((b.latitude - a.latitude) * Math.PI) / 180;
  const dLon = ((b.longitude - a.longitude) * Math.PI) / 180;

  const lat1 = (a.latitude * Math.PI) / 180;
  const lat2 = (b.latitude * Math.PI) / 180;

  const x =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.sin(dLon / 2) *
      Math.sin(dLon / 2) *
      Math.cos(lat1) *
      Math.cos(lat2);

  const y = 2 * Math.atan2(Math.sqrt(x), Math.sqrt(1 - x));

  return R * y;
};

