const confirmStartTimer = async (
  id: string | number,
  useGps = false
) => {
  console.log('CONFIRM START TIMER CALLED', id, useGps);

  const activeGoalId = getActiveRunningGoalId();

  if (
    activeGoalId &&
    String(activeGoalId) !== String(id)
  ) {
    setGpsModalGoalId(null);

    setNoticeModal({
      title: '이미 기록 중인 목표가 있어요',
      message:
        `${getRunningGoalTitle()} 기록을 먼저 종료한 뒤 ` +
        '다른 시간기록을 시작할 수 있어요.',
    });

    return;
  }

  setGpsModalGoalId(null);

  const startedAt = new Date().toISOString();

  const goal = actionGoals.find(
    (item) => String(item.id) === String(id)
  );

  console.log('TIMER GOAL FOUND', goal?.title);

  let finalUseGps = useGps;

  if (useGps) {
    const { status } =
      await Location.requestForegroundPermissionsAsync();

    if (status !== 'granted') {
      setNoticeModal({
        title: '위치 권한 필요',
        message:
          'GPS 기록을 사용하려면 위치 권한이 필요해요. GPS 없이 시간을 기록할게요.',
      });

      finalUseGps = false;
    }
  }

  try {
    await showTimerNotification(
      goal?.title ?? '시간기록형 목표',
      0,
      0,
      finalUseGps
    );

    console.log('TIMER NOTIFICATION SHOWN');
  } catch (e) {
    console.log('TIMER NOTIFICATION ERROR', e);

    setNoticeModal({
      title: '알림 생성 실패',
      message: String(e),
    });
  }

  setRunningGoalId(id);
  setTimerSeconds(0);
  setTimerStartAt(startedAt);

  const currentData = getRootOnboardingData() ?? onboardingData;

  const next = {
    ...currentData,
    runningTimer: {
      goalId: id,
      startedAt,
      gpsEnabled: finalUseGps,
    },
  };

  await saveRootData(next);

  await updateRootWidgetData();

  console.log(
    'RUNNING TIMER SAVED',
    getRootOnboardingData()?.runningTimer
  );

  setGpsEnabled(finalUseGps);
  setGpsDistanceKm(0);
  setGpsCoordinates([]);

  if (!finalUseGps) return;

  try {
    const firstLocation =
      await Location.getCurrentPositionAsync({
        accuracy: Location.Accuracy.High,
      });

    const firstPoint = {
      latitude: firstLocation.coords.latitude,
      longitude: firstLocation.coords.longitude,
      timestamp: firstLocation.timestamp,
    };

    console.log('GPS FIRST POINT', firstPoint);

    setGpsCoordinates([firstPoint]);

    const subscription =
      await Location.watchPositionAsync(
        {
          accuracy: Location.Accuracy.High,
          timeInterval: 3000,
          distanceInterval: 5,
        },
        (location) => {
          const point = {
            latitude: location.coords.latitude,
            longitude: location.coords.longitude,
            timestamp: location.timestamp,
          };

          console.log('GPS POINT', point);

          setGpsCoordinates((prev: any[]) => {
            if (prev.length === 0) {
              return [point];
            }

            const last = prev[prev.length - 1];
            const addedDistance = getDistanceKm(last, point);

            console.log('GPS ADDED DISTANCE', addedDistance);

            if (addedDistance < 0.005) {
              return prev;
            }

            setGpsDistanceKm((distance: number) =>
              Number((distance + addedDistance).toFixed(3))
            );

            return [...prev, point];
          });
        }
      );

    console.log('GPS WATCH STARTED');

    setLocationSubscription(subscription);
  } catch (e) {
    console.log('GPS START ERROR', e);

    setGpsEnabled(false);

    const currentData =
      getRootOnboardingData() ?? onboardingData;

    const next = {
      ...currentData,
      runningTimer: {
        goalId: id,
        startedAt,
        gpsEnabled: false,
      },
    };

    await saveRootData(next);
    await updateRootWidgetData();

    setNoticeModal({
      title: 'GPS 시작 실패',
      message:
        '위치 정보를 가져오지 못했어요. GPS 없이 시간만 기록할게요.',
    });
  }
};

const stopTimerGoal = async (
  id: string | number
) => {
  const goal =
    actionGoals.find(
      (item) =>
        String(item.id) ===
        String(id)
    );

  console.log(
    'TIMER STOP PRESSED',
    {
      requestedGoalId:
        String(id),

      foundGoalId:
        goal?.id ?? null,

      title:
        goal?.title ?? null,

      category:
        goal?.category ?? null,

      type:
        goal?.type ?? null,

      timerStartAt,
      timerSeconds,
    }
  );

  if (!goal) {
    console.log(
      'TIMER STOP FAILED: GOAL NOT FOUND',
      id
    );

    setNoticeModal({
      title: '기록 종료 실패',
      message:
        '시간기록 중인 행동목표를 찾지 못했어요.',
    });

    return;
  }

  /*
   * state를 초기화하기 전에
   * 시작 시각과 측정 시간을 복사합니다.
   */
  const savedTimerStartAt =
    timerStartAt;

  const seconds =
    savedTimerStartAt
      ? Math.max(
          0,
          Math.floor(
            (
              Date.now() -
              new Date(
                savedTimerStartAt
              ).getTime()
            ) / 1000
          )
        )
      : Math.max(
          0,
          timerSeconds
        );

  const minutes =
    Math.max(
      1,
      Math.ceil(
        seconds / 60
      )
    );

  try {
    if (
      locationSubscription
    ) {
      locationSubscription.remove();
    }
  } catch (error) {
    console.log(
      'GPS STOP ERROR',
      error
    );
  }

  setLocationSubscription(
    null
  );

  setRunningGoalId(
    null
  );

  setTimerSeconds(
    0
  );

  /*
   * 여기에서는 timerStartAt을
   * null로 만들면 안 됩니다.
   *
   * saveCompleteRecord가 시작 시각을
   * 사용한 뒤 초기화해야 합니다.
   */

  void cancelTimerNotification()
    .catch((error) => {
      console.log(
        'TIMER NOTIFICATION CANCEL ERROR',
        error
      );
    });

  const currentData =
    getRootOnboardingData() ??
    onboardingData ??
    {};

  const nextData = {
    ...currentData,
    runningTimer: null,
  };

  try {
    /*
     * Firestore를 기다리지 않고
     * 실행 중 상태만 로컬에 먼저 저장합니다.
     */
    await saveRootOnboardingData(
      nextData
    );

    setOnboardingData(
      nextData
    );

    console.log(
      'TIMER STOP LOCAL STATE SAVED',
      {
        goalId:
          goal.id,

        title:
          goal.title,

        minutes,
      }
    );
  } catch (error) {
    console.log(
      'TIMER STOP LOCAL STATE SAVE ERROR',
      error
    );

    /*
     * 실행 상태 저장에 실패하더라도
     * 기록 저장 모달은 열어줍니다.
     */
  }

  /*
   * 위젯 동기화보다 기록 저장 모달을
   * 먼저 엽니다.
   */
  openRecordModal(
    goal,
    minutes
  );

  console.log(
    'TIMER RECORD MODAL OPEN',
    {
      goalId:
        goal.id,

      title:
        goal.title,

      category:
        goal.category,

      type:
        goal.type,

      minutes,

      startedAt:
        savedTimerStartAt,
    }
  );

  /*
   * 위젯 동기화는 모달을 막지 않도록
   * 뒤에서 실행합니다.
   */
  void updateRootWidgetData()
    .catch((error) => {
      console.log(
        'TIMER STOP WIDGET SYNC ERROR',
        error
      );
    });
};

  const openRecordModal = (goal: any, minutes = 0) => {
  setPendingCompleteGoal(goal);
  setPendingMinutes(minutes);
  setSelectedPhoto(null);
  setDecoratedPhotoUri(null);
  setRecordMemo('');
  setFocusRating(5);
  setDecorateStickers([]);
  setDecorateModalVisible(false);
  setShowCustomStickerModal(false);
  setCustomStickerText('');
  setRecordModalVisible(true);
};

const pickPhotoFromGallery = async () => {
  const result = await ImagePicker.launchImageLibraryAsync({
    mediaTypes: ['images'],
    allowsEditing: true,
    quality: 0.8,
  });

  if (!result.canceled) {
  setSelectedPhoto(result.assets[0]);
    setDecoratedPhotoUri(null);
  setDecorateStickers([]);
}
};

const takePhoto = async () => {
  const permission = await ImagePicker.requestCameraPermissionsAsync();

  if (!permission.granted) {
    setNoticeModal({
  title: '카메라 권한 필요',
  message:
    '사진을 찍으려면 카메라 권한이 필요해요.',
});
    return;
  }

  const result = await ImagePicker.launchCameraAsync({
    allowsEditing: true,
    quality: 0.8,
  });

  if (!result.canceled) {
  setSelectedPhoto(result.assets[0]);
  setDecoratedPhotoUri(null);
  setDecorateStickers([]);
}
};

const isDecorateTimerGoal = () => {
  return (
    pendingCompleteGoal?.type === '시간기록형' ||
    pendingCompleteGoal?.type === 'timer' ||
    pendingMinutes > 0
  );
};

const getPreviewBurnedCalories = () => {
  const previewCategory =
  String(
    pendingCompleteGoal
      ?.category ??
      ''
  ).trim();

if (
  previewCategory !==
    'exercise' &&
  previewCategory !==
    '운동'
) {
  return 0;
}

  const met = Number(pendingCompleteGoal?.met ?? 0);
  const minutes = Number(pendingMinutes ?? 0);

  if (!met || !minutes) {
    return 0;
  }

  return Math.round(
    met * calorieWeight * (minutes / 60)
  );
};

